{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C52", "C51", "C59", "C54", "C71", "C69", "C70", "C66", "C72", "C62", "C73", "C65"],
  "contradictory_card_ids": ["C02", "C01", "C05", "C10"],
  "prediction_basis_card_ids": ["C52", "C51", "C59", "C54", "C71", "C69", "C70", "C66", "C72"],
  "claims": [
    {
      "claim": "L4 measured aqueous solubility for structurally related large pyrrolidine carbamate–imidazole HCV inhibitors is very low (parent PIB <0.1 mg/mL at pH 7.4, C52; phosphate prodrug 6.4 µg/mL, C51), and atazanavir, a comparably sized peptidomimetic carbamate, is <1 µg/mL at pH≥4 with only 30.56% pure-drug dissolution (C59, C54), supporting poor dissolution/absorption for this chemotype.",
      "card_ids": ["C52", "C51", "C59", "C54"]
    },
    {
      "claim": "L5 identifies multiple HCV NS5A inhibitors of the same structural class (pibrentasvir, ledipasvir, ombitasvir, velpatasvir) as P-gp/BCRP substrates whose intestinal efflux can reduce oral exposure (C71, C69, C70, C66, C72), and P-gp inhibition increases exposure for repaglinide, rovatirelin, and sulpiride (C73, C63, C65), providing mechanistic evidence for presystemic loss in the query.",
      "card_ids": ["C71", "C69", "C70", "C66", "C72", "C73", "C63", "C65"]
    },
    {
      "claim": "L1 high-F contexts (acalabrutinib 25.3%, AZD0837 22–55%, maraviroc 33%, asciminib ~73%) are direct but poorly transferable because the query is much larger (MW 738.9), more lipophilic (logP 6.22), and has higher TPSA (174.6) (C02, C01, C05, C10).",
      "card_ids": ["C02", "C01", "C05", "C10"]
    },
    {
      "claim": "No direct F measurement for the query is available; the low prediction rests on coherent measured solubility and efflux liabilities in close analogs plus the unfavorable physicochemical prior, not on generic descriptors alone.",
      "card_ids": ["C52", "C51", "C71", "C69"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C71", "C69", "C70", "C66", "C72", "C62", "C73", "C65", "C63"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule.",
    "No query-specific permeability (e.g., Caco-2/PAMPA) or intestinal absorption data; L4 contains solubility/dissolution records only.",
    "No query-specific efflux or intestinal metabolism assay; L5 substrate status is for related HCV NS5A inhibitors, not the query itself.",
    "No dose, formulation, or food-effect information for the query, which could alter the impact of low intrinsic solubility and efflux.",
    "L1 F measurements are for other molecules with limited structural transferability to this large symmetric dimer."
  ],
  "decision_summary": "L5 adds mechanistic gut-wall efflux evidence showing that related HCV NS5A inhibitors (pibrentasvir, ledipasvir, ombitasvir, velpatasvir) are P-gp/BCRP substrates whose intestinal efflux can reduce oral exposure, coherently supporting presystemic loss for the query. Combined with L4 measured low solubility in the same chemotype and the unfavorable physicochemical prior, the evidence supports F < 20%; L1 high-F contexts remain direct but poorly transferable. Prediction kept low with moderate confidence."
}

